def reference_vector(encoded):
    return list(struct.unpack("<256f", base64.b64decode(encoded)))


@unittest.skipUnless((MODEL / "model.safetensors").is_file(), "blink-8M is not downloaded")
class ReferenceParity(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.model = embed.Embedder(MODEL)

    @classmethod
    def tearDownClass(cls):
        cls.model.close()

    def test_twenty_sentences_tokenise_exactly_like_the_reference(self):
        self.assertEqual(len(REFERENCE), 20)
        for text, ids, _ in REFERENCE:
            with self.subTest(text=text):
                self.assertEqual(self.model.token_ids(text), ids)

    def test_vectors_match_the_reference_to_four_nines(self):
        for text, _, encoded in REFERENCE:
            with self.subTest(text=text):
                expected = reference_vector(encoded)
                got = self.model.embed(text)
                self.assertEqual(len(got), 256)
                if not any(expected):
                    self.assertFalse(any(got), "nothing known gives the zero vector")
                    continue
                self.assertGreaterEqual(embed.cosine(got, expected), 0.9999)
                self.assertAlmostEqual(math.sqrt(embed.dot(got, got)), 1.0, places=6)

    def test_a_sentence_costs_at_most_two_milliseconds(self):
        texts = [text for text, _, _ in REFERENCE]
        for text in texts:
            self.model.embed(text)
        rounds = 20
        start = time.perf_counter()
        for _ in range(rounds):
            self.model._cache.clear()
            for text in texts:
                self.model.embed(text)
        per_sentence = (time.perf_counter() - start) / (rounds * len(texts))
        self.assertLess(per_sentence, 0.002, f"{per_sentence * 1000:.3f} ms per sentence")

    def test_quantised_codes_keep_the_ranking(self):
        a, b = self.model.embed("my orchid is called Silverleaf"), self.model.embed("what is my flower called")
        scale_a, codes_a = embed.quantise(a)
        exact = embed.dot(a, b)
        approx = embed.dot(b, embed.codes(codes_a)) * scale_a
        self.assertAlmostEqual(exact, approx, delta=0.01)
        self.assertEqual(len(codes_a), 256)


@unittest.skipUnless((MODEL / "model.safetensors").is_file(), "blink-8M is not downloaded")
@unittest.skipUnless(sys.platform.startswith("linux") or sys.platform == "darwin", "needs getrusage")
class ResidentMemory(unittest.TestCase):
    def test_loading_and_using_the_model_costs_at_most_40_mb(self):
        # A fresh interpreter, so other tests' allocations do not count.
        import subprocess

        code = (
            "import resource, sys; from mind import embed\n"
            "before = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss\n"
            f"m = embed.Embedder({str(MODEL)!r})\n"
            "for i in range(2000): m.embed(f'sentence number {i} about orchids gardens and the weather')\n"
            "after = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss\n"
            "scale = 1 if sys.platform == 'darwin' else 1024\n"
            "print((after - before) * scale)\n"
        )
        root = Path(__file__).resolve().parents[1]
        out = subprocess.run([sys.executable, "-c", code], cwd=root, capture_output=True, text=True, check=True)
        grown = int(out.stdout.strip())
        self.assertLessEqual(grown, 40 * 1024 * 1024, f"{grown / 1e6:.1f} MB")


class Tokeniser(unittest.TestCase):
    def test_normaliser_cleans_spaces_controls_accents_and_case(self):
        self.assertEqual(embed.normalise("Caf\u00e9\tD\u00c9J\u00c0\u0007 vu"), "cafe deja vu")
        self.assertEqual(embed.normalise("\u6771\u4eac"), " \u6771  \u4eac ")
        self.assertEqual(embed.normalise("a\u00a0b\u200bc"), "a bc")

    def test_pre_tokeniser_isolates_punctuation(self):
        self.assertEqual(embed.pre_tokenise("it's 9:30, ok?"), ["it", "'", "s", "9", ":", "30", ",", "ok", "?"])

    def test_missing_files_are_reported_not_raised_to_the_mind(self):
        missing = Path(__file__).parent / "no-such-model"
        with self.assertRaises(embed.Unavailable):
            embed.Embedder(missing)
        self.assertIsNone(embed.load(missing))

    def test_an_empty_override_switches_the_model_off(self):
        old = os.environ.get("BEING_EMBED_DIR")
        os.environ["BEING_EMBED_DIR"] = ""
        try:
            self.assertIsNone(embed.model_dir())
        finally:
            if old is None:
                del os.environ["BEING_EMBED_DIR"]
            else:
                os.environ["BEING_EMBED_DIR"] = old


if __name__ == "__main__":
    unittest.main()
